// BEFORE: one switch, in one function, unchanged for 14 months
-function badgeColor(status: 'open' | 'closed'): string {
-  switch (status) {
-    case 'open': return 'green';
-    case 'closed': return 'gray';
-  }
-}

// AFTER: "replaced the conditional with polymorphism"
+interface Status { badgeColor(): string; }
+class OpenStatus implements Status { badgeColor() { return 'green'; } }
+class ClosedStatus implements Status { badgeColor() { return 'gray'; } }
+class StatusFactory {
+  static from(s: string): Status {
+    switch (s) {                      // the switch we 'removed', reborn here
+      case 'open': return new OpenStatus();
+      case 'closed': return new ClosedStatus();
+      default: throw new Error('unknown status');
+    }
+  }
+}

// ALSO in this PR: a base UI component reused via inheritance
+class StaticBanner extends Button {
+  onClick(): void { /* banners aren't clickable - intentionally empty */ }
+}
